            approvedAt: 'Today, ' + new Date().toTimeString().slice(0, 5) + ' WAT',
            method: 'Verified by email code',
            conditions: cs,
            note: x.source === 'link' ? 'Approved ' + x.url.replace('https://', '') + (x.releaseId ? ' · ' + x.releaseId : '') + ' · as reviewed on ' + x.capturedAt : 'Approved exactly this frozen copy (' + x.checksum + ')'
